const item = $input.first()?.json || {};
const headers = item.headers || {};
const isWebhook = Boolean(item.headers && (item.body !== undefined || item.webhookUrl));

if (isWebhook) {
  const expected = ($env && $env.CHATLYTICS_N8N_SECRET) ? String($env.CHATLYTICS_N8N_SECRET).trim() : '';
  const provided = String(headers['x-n8n-secret'] || headers['X-N8N-Secret'] || headers['x-chatlytics-cron-key'] || '').trim();
  if (expected && provided !== expected) {
    throw new Error('Unauthorized webhook invocation: invalid X-N8N-Secret header');
  }
}

return [{
  json: {
    trigger_source: isWebhook ? 'webhook' : 'schedule',
    requested_by: isWebhook ? String(item.body?.requested_by || 'admin') : 'weekly_cron',
    started_at: new Date().toISOString()
  }
}];

const triggerMeta = $('Normalize & Verify Trigger').first().json || {};
const catalogResp = $('Fetch Tracked Catalog (Chatlytics PHP)').first().json || {};
const catalogData = catalogResp.data || catalogResp;
const trackedModels = Array.isArray(catalogData.tracked_models) ? catalogData.tracked_models : [];
const knownCatalogIds = new Set(
  (Array.isArray(catalogData.catalog_model_ids) ? catalogData.catalog_model_ids : [])
    .map(id => String(id || '').trim().toLowerCase())
    .filter(Boolean)
);

const orResp = $input.first()?.json || {};
const rawOrModels = Array.isArray(orResp.data) ? orResp.data : [];

const blockedFragments = [
  'embedding', 'embed', 'tts', 'whisper', 'dall-e', 'sora', 'imagen',
  'veo', 'lyria', 'music', 'moderation', 'guard', 'realtime',
  '-image', 'image-preview', 'flux', 'midjourney', 'audio', 'speech', ':free'
];

const liveMap = new Map();
for (const m of rawOrModels) {
  if (!m || typeof m.id !== 'string') continue;
  const rawId = m.id.trim();
  if (!rawId || rawId.includes('~')) continue;
  const baseId = rawId.replace(/:(batch|online)$/i, '');
  const lower = baseId.toLowerCase();
  if (!liveMap.has(lower)) {
    liveMap.set(lower, {
      id: baseId,
      name: m.name || baseId,
      description: String(m.description || ''),
      created: Number(m.created || 0),
      expiration_date: m.expiration_date || m.deprecated_at || null,
      is_deprecated: Boolean(m.deprecated || m.is_deprecated),
      architecture: m.architecture || {}
    });
  }
}

const deterministicAlerts = [];
const trackedProviders = new Set();
const eolRegex = /\b(deprecated|end[- ]of[- ]life|will be retired|sunset(?:ting)?|discontinued)\b/i;

for (const tm of trackedModels) {
  const id = String(tm.id || '').trim();
  if (!id) continue;
  const lower = id.toLowerCase();
  const provider = String(tm.provider || (id.includes('/') ? id.split('/')[0] : '')).toLowerCase();
  if (provider) trackedProviders.add(provider);
  knownCatalogIds.add(lower);

  const live = liveMap.get(lower);
  if (!live) {
    deterministicAlerts.push({
      alert_type: 'model_missing_openrouter',
      severity: 'critical',
      current_model_id: id,
      suggested_model_id: null,
      suggested_display_name: null,
      confidence_score: 100,
      reason_de: `Der Modell-Slug '${id}' ist nicht mehr im Live-Katalog von OpenRouter gelistet (möglicherweise abgeschaltet oder umbenannt).`,
      reason_en: `Model slug '${id}' is no longer listed in the live OpenRouter catalog (possibly retired or renamed).`,
      source_url: 'https://openrouter.ai/models'
    });
    continue;
  }

  if (live.is_deprecated || live.expiration_date || eolRegex.test(live.description)) {
    const expInfo = live.expiration_date ? ` (Ablaufdatum: ${live.expiration_date})` : '';
    deterministicAlerts.push({
      alert_type: 'model_eol',
      severity: 'critical',
      current_model_id: id,
      suggested_model_id: null,
      suggested_display_name: null,
      confidence_score: 95,
      reason_de: `OpenRouter meldet einen Deprecation-/EOL-Hinweis für '${id}'${expInfo}.`,
      reason_en: `OpenRouter metadata flags '${id}' as deprecated or approaching end-of-life${expInfo}.`,
      source_url: `https://openrouter.ai/${id}`
    });
  }
}

// Collect genuinely new text models from the same provider namespaces
const candidatesByProvider = {};
for (const [lower, live] of liveMap.entries()) {
  if (knownCatalogIds.has(lower)) continue;
  if (!live.id.includes('/')) continue;
  const prov = live.id.split('/')[0].toLowerCase();
  if (!trackedProviders.has(prov)) continue;
  if (blockedFragments.some(frag => lower.includes(frag))) continue;

  const arch = live.architecture || {};
  const inMods = Array.isArray(arch.input_modalities) ? arch.input_modalities.map(x => String(x).toLowerCase()) : ['text'];
  const outMods = Array.isArray(arch.output_modalities) ? arch.output_modalities.map(x => String(x).toLowerCase()) : ['text'];
  if (!inMods.includes('text') || !outMods.includes('text')) continue;
  if (outMods.includes('image') || outMods.includes('audio') || outMods.includes('video')) continue;

  if (!candidatesByProvider[prov]) candidatesByProvider[prov] = [];
  candidatesByProvider[prov].push({
    id: live.id,
    name: live.name,
    created: live.created
  });
}

let candidateCount = 0;
for (const prov of Object.keys(candidatesByProvider)) {
  candidatesByProvider[prov].sort((a, b) => (b.created - a.created) || a.id.localeCompare(b.id));
  candidatesByProvider[prov] = candidatesByProvider[prov].slice(0, 12);
  candidateCount += candidatesByProvider[prov].length;
}

return [{
  json: {
    trigger_source: triggerMeta.trigger_source || 'schedule',
    tracked_models: trackedModels,
    deterministic_alerts: deterministicAlerts,
    candidates_by_provider: candidatesByProvider,
    live_model_ids: Array.from(liveMap.values()).map(m => ({ id: m.id, name: m.name })),
    candidate_count: candidateCount,
    has_candidates: candidateCount > 0 && trackedModels.length > 0
  }
}];

const diffData = $('Deterministic EOL & Candidate Diff').first().json || {};
const deterministic = Array.isArray(diffData.deterministic_alerts) ? diffData.deterministic_alerts : [];
const liveNameById = new Map(
  (Array.isArray(diffData.live_model_ids) ? diffData.live_model_ids : [])
    .map(m => [String(m.id || '').toLowerCase(), m.name || m.id])
);
const trackedIds = new Set(
  (Array.isArray(diffData.tracked_models) ? diffData.tracked_models : [])
    .map(m => String(m.id || '').toLowerCase())
);

let llmAlerts = [];
const inputJson = $input.first()?.json || {};
if (inputJson.choices && Array.isArray(inputJson.choices) && inputJson.choices[0]?.message?.content) {
  try {
    const rawContent = String(inputJson.choices[0].message.content).trim();
    const cleaned = rawContent.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
    const parsed = JSON.parse(cleaned);
    if (Array.isArray(parsed.alerts)) {
      llmAlerts = parsed.alerts;
    }
  } catch (_) {
    llmAlerts = [];
  }
}

const merged = [];
const seenKeys = new Set();

const addAlert = (a) => {
  if (!a || typeof a !== 'object') return;
  const currentId = String(a.current_model_id || '').trim();
  if (!currentId || !trackedIds.has(currentId.toLowerCase())) return;

  const alertType = ['successor_available', 'model_eol', 'model_missing_openrouter'].includes(a.alert_type)
    ? a.alert_type
    : 'successor_available';
  const confidence = Number(a.confidence_score ?? 85);
  if (alertType === 'successor_available' && confidence < 75) return;

  let suggestedId = a.suggested_model_id ? String(a.suggested_model_id).trim() : null;
  if (alertType === 'successor_available') {
    if (!suggestedId || !liveNameById.has(suggestedId.toLowerCase())) return;
    if (suggestedId.toLowerCase() === currentId.toLowerCase()) return;
  }

  const key = `${alertType}|${currentId.toLowerCase()}|${(suggestedId || '').toLowerCase()}`;
  if (seenKeys.has(key)) return;
  seenKeys.add(key);

  merged.push({
    alert_type: alertType,
    severity: ['critical', 'warning', 'info'].includes(a.severity)
      ? a.severity
      : (alertType === 'successor_available' ? 'info' : 'critical'),
    current_model_id: currentId,
    suggested_model_id: suggestedId,
    suggested_display_name: a.suggested_display_name || (suggestedId ? (liveNameById.get(suggestedId.toLowerCase()) || suggestedId) : null),
    confidence_score: Math.max(0, Math.min(100, Math.round(confidence))),
    reason_de: String(a.reason_de || a.reason_en || ''),
    reason_en: String(a.reason_en || a.reason_de || ''),
    source_url: typeof a.source_url === 'string' && /^https?:\/\//i.test(a.source_url) ? a.source_url : null
  });
};

deterministic.forEach(addAlert);
llmAlerts.forEach(addAlert);

return [{
  json: {
    trigger_source: diffData.trigger_source || 'schedule',
    alerts: merged,
    mark_email_notified: true
  }
}];

const resp = $input.first()?.json || {};
const payload = resp.data || resp;
const newAlerts = Array.isArray(payload.new_alerts) ? payload.new_alerts : [];
const adminEmails = Array.isArray(payload.admin_emails) && payload.admin_emails.length > 0
  ? payload.admin_emails
  : ['admin@chatlytics.de'];
const dashboardUrl = String(payload.dashboard_url || 'https://chatlytics.de/admin.html#models');

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const eolCount = newAlerts.filter(a => a.alert_type !== 'successor_available').length;
const succCount = newAlerts.filter(a => a.alert_type === 'successor_available').length;
const subject = `[Chatlytics Model-Watcher] ${newAlerts.length} neue Modell-Hinweise (${eolCount} EOL / ${succCount} Nachfolger)`;

const rowsHtml = newAlerts.map(a => {
  const badge = a.alert_type === 'successor_available' ? 'Nachfolger verfügbar' : 'EOL / Fehlt auf OpenRouter';
  const arrow = a.suggested_model_id ? ` &rarr; <code>${esc(a.suggested_model_id)}</code>` : '';
  const presets = Array.isArray(a.affected_presets) && a.affected_presets.length > 0
    ? `<br><small style="color:#475569">Betroffene Analyse-Sets: ${esc(a.affected_presets.join(', '))} · Aktive Profile: ${Number(a.affected_configs_count || 0)}</small>`
    : '';
  return `<li style="margin-bottom:14px;padding:12px;border:1px solid #e2e8f0;border-radius:8px;"><strong>[${esc(badge)}]</strong> <code>${esc(a.current_model_id)}</code>${arrow} <span style="color:#64748b">(${Number(a.confidence_score || 0)}%)</span><br><span style="color:#0f172a">${esc(a.reason_de || a.reason_en || '')}</span>${presets}</li>`;
}).join('');

const htmlBody = `
<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;max-width:640px;margin:0 auto;color:#0f172a;">
  <h2 style="margin-bottom:8px;">Chatlytics Modell-Überwachung</h2>
  <p style="color:#475569;margin-top:0;">Der automatische Predecessor/Successor-Watcher hat <strong>${newAlerts.length} neue(n) Hinweis(e)</strong> für Ihre überwachten OpenRouter-Modelle gefunden:</p>
  <ul style="list-style:none;padding:0;margin:16px 0;">${rowsHtml}</ul>
  <p style="margin-top:20px;"><a href="${esc(dashboardUrl)}" style="display:inline-block;padding:10px 18px;background:#0f172a;color:#ffffff;text-decoration:none;border-radius:6px;font-weight:600;">Im Admin-Cockpit prüfen &amp; anwenden &rarr;</a></p>
  <p style="font-size:12px;color:#64748b;margin-top:24px;">Keine automatische Umstellung durchgeführt. Sie können im Admin-Cockpit per 1-Klick entscheiden, ob das Modell in Analyse-Sets ersetzt, freigegeben oder ignoriert werden soll.</p>
</div>`;

const textLines = newAlerts.map(a => `- [${a.alert_type}] ${a.current_model_id}${a.suggested_model_id ? ' -> ' + a.suggested_model_id : ''} (${a.confidence_score}%): ${a.reason_de || a.reason_en || ''}`);
const textBody = `Chatlytics Model-Watcher: ${newAlerts.length} neue Modell-Hinweise\n\n${textLines.join('\n')}\n\nAdmin-Cockpit: ${dashboardUrl}`;

return [{
  json: {
    to_email: adminEmails.join(', '),
    subject,
    html_body: htmlBody,
    text_body: textBody,
    ingest_result: payload
  }
}];

const triggerMeta = $('Normalize & Verify Trigger').first().json || {};
const ingestResp = $('Ingest Alerts to Chatlytics PHP').first().json || {};
const payload = ingestResp.data || ingestResp;
return [{
  json: {
    status: 'ok',
    trigger_source: triggerMeta.trigger_source || 'schedule',
    ingested_count: Number(payload.ingested_count || 0),
    new_count: Number(payload.new_count || 0),
    open_alerts_count: Number(payload.open_alerts_count || 0),
    should_notify_email: Boolean(payload.should_notify_email)
  }
}];
